def pick_colors():
    # цвет игрока и цвета ботов: если игрок взял цвет, который был у бота, бот получает жёлтый (прежний цвет игрока)
    pc = PLAYER_COLORS[sel_color][1]
    return pc, [YEL if c == pc else c for c in BOT_BASE_COLORS]
def apply_skin(pl):
    if sel_skin >= 0: pl.skin = sel_skin
    return pl

def rst():
    REG['lab'] = None; REG['elab'] = None; REG['spots'] = []; REG['crowd'] = False  # карта прошлого раунда не должна влиять на новый
    # Формат поверхности совпадает с экраном: быстрее выводится каждый кадр.
    sf = pg.Surface((AW, AH)).convert(); sf.fill(ABG)
    sp = spw_all(6)
    
    pc_, bc_ = pick_colors()
    player = apply_skin(P(*sp[0], pc_))
    bots = [
        P(*sp[1], bc_[0], True),
        P(*sp[2], bc_[1], True),
        P(*sp[3], bc_[2], True),
        P(*sp[4], bc_[3], True),
        P(*sp[5], bc_[4], True)
    ]
    # Неактивные слоты остаются в списке для совместимости с таблицей очков,
    # но не участвуют в раунде, столкновениях и логике ботов.
    for _i, _bot in enumerate(bots):
        if not BOT_ENABLED[_i]: _bot.alv = False
    return sf, player, bots, []

def rst_solo():
    REG['lab'] = None; REG['elab'] = None; REG['spots'] = []; REG['crowd'] = False
    # Отдельная арена без противников и без системы очков.
    sf = pg.Surface((AW, AH)).convert(); sf.fill(ABG)
    sp = spw_all(1)[0]
    player = apply_skin(P(*sp, PLAYER_COLORS[sel_color][1]))
    # В соло нет просадки FPS от ботов, поэтому задаём более спокойный темп.
    # Поворот снижен пропорционально скорости, чтобы радиус манёвра оставался привычным.
    player.base_speed = 1.00
    player.base_turn = 0.041
    player.gap_duration = 20  # в соло отверстия в следе увеличены; боты остаются без изменений
    player.bonus_duration_multiplier = 1.5  # бонусы в соло действуют на 50% дольше
    player.cur_speed, player.cur_turn = player.base_speed, player.base_turn
    # При низкой скорости прежняя задержка в 6 точек оставляла след слишком близко к голове.
    # Увеличиваем её только для соло, чтобы голова не задевала собственный след на прямом ходу.
    player.trail_delay = 12
    return sf, player, [], []

