def _sk_cells(n, cols):
    top, bottom = int(H * 0.085), sk_back_btn.y - M
    rows = (n + cols - 1) // cols
    cw, ch = (W - M * (cols + 1)) // cols, (bottom - top - M * (rows - 1)) // rows
    return [pg.Rect(M + (i % cols) * (cw + M), top + (i // cols) * (ch + M), cw, ch) for i in range(n)]

def _icon_fit(i, w, h):
    key = (i, w, h)
    sf = _ICON_FIT.get(key)
    if sf is None:
        if not _ICON_SRC:
            for b in _ICON_B64: _ICON_SRC.append(pg.image.load(io.BytesIO(base64.b64decode(b)), "icon.png").convert())
        src = _ICON_SRC[i]
        k = min(w / src.get_width(), h / src.get_height())
        sf = pg.transform.smoothscale(src, (max(1, int(src.get_width() * k)), max(1, int(src.get_height() * k))))
        _ICON_FIT[key] = sf
    return sf

class _PrevS: pass

def _skin_preview_to(pic, sk, area):
    # Картинка скина (голова с плащом, как в игре) рисуется ПРЯМО на готовую страницу в пределах area.
    # Раньше для каждого скина создавались большая прозрачная поверхность и спрайт головы (~12 МБ на страницу),
    # а любая ошибка в рисовании роняла игру.
    pic.set_clip(area)
    try:
        if sk < 0:
            q = f_menu.render("?", True, (210, 210, 210))
            pic.blit(q, q.get_rect(center=area.center))
        else:
            r = max(6, min(56, int(min(area.w, area.h) * 0.17)))
            cx, cy = area.centerx, area.y + int(area.h * 0.40)
            s_ = _PrevS(); s_.skin = sk; s_.a = -m.pi / 2; s_.x = cx - AR.x; s_.y = cy - AR.y
            s_.cape_h = deque([(s_.x, s_.y + i * 2.0) for i in range(80)], maxlen=80)
            _draw_cape(pic, s_, r)
            _skin_head(pic, sk, cx, cy, 0.0, -1.0, r)   # угол -90 градусов: cos = 0, sin = -1
    finally:
        pic.set_clip(None)

