def skins_press(pos):
    global game_state, sk_page, sel_skin, sel_color
    if sk_back_btn.collidepoint(pos):
        if sk_page == "home": game_state = "MENU"
        else: sk_page = "home"
        return
    if sk_page == "home":
        if sk_skins_btn.collidepoint(pos): sk_page = "skins"
        elif sk_col_btn.collidepoint(pos): sk_page = "colors"
    elif sk_page == "skins":
        for i, rc in enumerate(_sk_cells(SKIN_COUNT + 1, 3)):
            if rc.collidepoint(pos): sel_skin = i - 1; prefs_save(); return
    else:
        for i, rc in enumerate(_sk_cells(len(PLAYER_COLORS), 3)):
            if rc.collidepoint(pos): sel_color = i; prefs_save(); return
