def safe_menu_press(pos):
    """Deduplicate SDL's FINGERDOWN + synthetic MOUSEBUTTONDOWN pair."""
    global _last_menu_press_pos, _last_menu_press_ms
    now = pg.time.get_ticks()
    if _last_menu_press_pos == tuple(pos) and now - _last_menu_press_ms < 120:
        return
    _last_menu_press_pos, _last_menu_press_ms = tuple(pos), now
    try:
        menu_press(pos)
    except Exception:
        _log_error("menu_press at " + str(pos))

