# Сенсорные зоны чуть больше видимых кнопок: палец не обязан попадать точно в край.
_profile_save_hit = profile_save_btn.inflate(max(24, int(W * 0.05)), max(24, int(H * 0.035)))
_profile_close_hit = profile_close_btn.inflate(max(24, int(W * 0.05)), max(24, int(H * 0.035)))

_PROFILE_SKIN_CACHE = {}
_PROFILE_FONT_CACHE = {}
_PROFILE_FIT_CACHE = {}
def profile_fit_text(txt, max_width, base_size, color=WHT):
    """Кэширует уже подобранный размер подписи: не перебирает шрифты каждый кадр."""
    txt = str(txt)
    max_width = max(1, int(max_width))
    base_size = max(10, int(base_size))
    key = (txt, max_width, base_size, tuple(color))
    cached = _PROFILE_FIT_CACHE.get(key)
    if cached is not None:
        return cached
    size = base_size
    while size > 10:
        font = _PROFILE_FONT_CACHE.get(size)
        if font is None:
            font = _PROFILE_FONT_CACHE[size] = pg.font.SysFont(None, size, bold=True)
        surf = font.render(txt, True, color).convert_alpha()
        if surf.get_width() <= max_width:
            break
        size -= 1
    font = _PROFILE_FONT_CACHE.get(size)
    if font is None:
        font = _PROFILE_FONT_CACHE[size] = pg.font.SysFont(None, size, bold=True)
    if size == 10:
        surf = font.render(txt, True, color).convert_alpha()
    if len(_PROFILE_FIT_CACHE) > 160:
        _PROFILE_FIT_CACHE.clear()
    _PROFILE_FIT_CACHE[key] = surf
    return surf

def profile_skin_surface(sk, size):
    key = (int(sk), tuple(size))
    surf = _PROFILE_SKIN_CACHE.get(key)
    if surf is None:
        surf = pg.Surface(size, pg.SRCALPHA)
        _skin_preview_to(surf, sk, surf.get_rect().inflate(-4, -4))
        if len(_PROFILE_SKIN_CACHE) > 12:
            _PROFILE_SKIN_CACHE.clear()
        _PROFILE_SKIN_CACHE[key] = surf
    return surf
target_score = 100
match_winner = None
input_mode = False
input_str = ""
last_finger = -10000
f_in = pg.font.SysFont(None, int(W * 0.06))
f_key = pg.font.SysFont(None, max(30, int(W * 0.050)))
f_small = pg.font.SysFont(None, int(W * 0.026))

# Окно очков: компактная панель, рассчитанная от реальной области экрана.
ip_w = min(int(W * 0.90), 620)
ip_h = min(int(H * 0.58), 720)
ip_h = max(430, ip_h)
ip_rect = pg.Rect(0, 0, ip_w, ip_h)
ip_rect.center = (W // 2, H // 2)
ip_mrg = max(12, int(ip_w * 0.045))
ip_gap = max(8, int(ip_w * 0.025))
ip_box_h = max(52, int(ip_h * 0.105))
ip_box = pg.Rect(ip_rect.x + ip_mrg, ip_rect.y + int(ip_h * 0.265),
                 ip_rect.w - ip_mrg * 2, ip_box_h)
ip_kw = (ip_rect.w - ip_mrg * 2 - ip_gap * 2) // 3
ip_key_gap_y = max(7, int(ip_h * 0.018))
ip_key_top = ip_rect.y + int(ip_h * 0.405)
ip_bottom_pad = max(16, int(ip_h * 0.045))
ip_kh = max(42, (ip_rect.bottom - ip_bottom_pad - ip_key_top - ip_key_gap_y * 3) // 4)
ip_keys = []
for _i, _lb in enumerate(["1", "2", "3", "4", "5", "6", "7", "8", "9", "<", "0", "OK"]):
    _r, _c = divmod(_i, 3)
    ip_keys.append((_lb, pg.Rect(ip_rect.x + ip_mrg + _c * (ip_kw + ip_gap),
                                 ip_key_top + _r * (ip_kh + ip_key_gap_y), ip_kw, ip_kh)))

def input_add(ch):
    global input_str
    if len(input_str) < 4 and not (input_str == "" and ch == "0"):
        if int(input_str + ch) <= 1000:
            input_str += ch

def input_ok():
    global input_mode, input_str, target_score
    if input_str:
        target_score = max(1, min(1000, int(input_str)))
    input_mode = False

def menu_press(pos):
    global game_state, input_mode, input_str, solo_mode, arn, p1, bots, bonuses, score_p1, score_bots, spawn_timer, round_start_tick, solo_dead_tick, net_page, net_status, paused, prev_alive_states
    # profile_nick MUST be global: without this declaration Python treats it as
    # a local variable and profile button handlers fail with UnboundLocalError.
    global profile_open, profile_nick, profile_nick_edit, profile_icon_alive, sel_color, profile_saved_until, BOT_ENABLED
    if game_state == "SETTINGS":
        if input_mode:
            for lb, rc in ip_keys:
                if rc.collidepoint(pos):
                    if lb == "<": input_str = input_str[:-1]
                    elif lb == "OK": input_ok()
                    else: input_add(lb)
                    return
            if not ip_rect.collidepoint(pos): input_mode = False
            return
        if settings_score_btn.collidepoint(pos):
            input_mode = True; input_str = ""
        elif settings_bots_btn.collidepoint(pos):
            input_mode = False; game_state = "BOT_SELECT"
        elif settings_back_btn.collidepoint(pos):
            input_mode = False; game_state = "MENU"
        return
    if game_state == "BOT_SELECT":
        if bot_back_btn.collidepoint(pos):
            game_state = "SETTINGS"; return
        for _i, _rc in enumerate(bot_icon_rects):
            if _rc.collidepoint(pos):
                _new = list(BOT_ENABLED)
                _new[_i] = not _new[_i]
                if any(_new):
                    BOT_ENABLED = _new; prefs_save()
                return
        return
    if profile_open:
        # Проверяем именно большие сенсорные зоны кнопок. Нажатие «ВЫЙТИ»
        # закрывает только окно профиля, а не всё приложение.
        if _profile_close_hit.collidepoint(pos) or profile_close_btn.collidepoint(pos):
            if not profile_nick.strip(): profile_nick = "Игрок"
            prefs_save()
            profile_open = False
            game_state = "MENU"
            profile_nick_edit = False
            profile_saved_until = 0
            try: pg.key.stop_text_input()
            except Exception: pass
        elif _profile_save_hit.collidepoint(pos) or profile_save_btn.collidepoint(pos):
            if not profile_nick.strip(): profile_nick = "Игрок"
            profile_nick_edit = False
            prefs_save()
            profile_saved_until = pg.time.get_ticks() + 2200
            try: pg.key.stop_text_input()
            except Exception: pass
        elif profile_nick_rect.collidepoint(pos):
            if not profile_nick_edit: profile_nick = ""  # новое имя вводится вместо старого
            profile_nick_edit = True
            try:
                pg.key.start_text_input()
                # SDL/Android IME uses this rectangle to place the native keyboard.
                if hasattr(pg.key, "set_text_input_rect"):
                    pg.key.set_text_input_rect(profile_nick_rect)
            except Exception: pass
        elif profile_icon_toggle.collidepoint(pos):
            profile_icon_alive = not profile_icon_alive
            prefs_save()
        elif not profile_panel.collidepoint(pos):
            if not profile_nick.strip(): profile_nick = "Игрок"
            prefs_save()
            profile_open = False; profile_nick_edit = False; game_state = "MENU"
            try: pg.key.stop_text_input()
            except Exception: pass
        return
    if profile_btn.collidepoint(pos):
        profile_open = True
        profile_nick_edit = False
        game_state = "PROFILE"
        return
    if knockout_btn.collidepoint(pos) or rating_btn.collidepoint(pos):
        return  # заглушки: пока не запускают режим и ничего не меняют
    if input_mode:
        for lb, rc in ip_keys:
            if rc.collidepoint(pos):
                if lb == "<": input_str = input_str[:-1]
                elif lb == "OK": input_ok()
                else: input_add(lb)
                return
        if not ip_rect.collidepoint(pos):
            input_mode = False
        return
    if start_btn.collidepoint(pos):
        solo_mode = False
        set_arena('bots')
        paused = False
        score_p1 = 0; score_bots = [0] * 5
        arn, p1, bots, bonuses = rst()
        prev_alive_states = [p1.alv] + [b.alv for b in bots]
        spawn_timer = 0; round_start_tick = pg.time.get_ticks()
        game_state = "GAME"
    elif solo_btn.collidepoint(pos):
        solo_mode = True
        set_arena(True)
        arn, p1, bots, bonuses = rst_solo()
        score_p1 = 0; score_bots = [0] * 5
        spawn_timer = 0; round_start_tick = pg.time.get_ticks(); solo_dead_tick = 0
        drops.clear()
        game_state = "GAME"
    elif online_btn.collidepoint(pos):
        set_arena(False)
        game_state = "ONLINE"
        net_page = "menu"
        net_status = ""
    elif wp_btn.collidepoint(pos):
        input_mode = False
        game_state = "SETTINGS"
    elif skins_btn.collidepoint(pos):
        global sk_page
        sk_page = "home"
        game_state = "SKINS"
# Постоянная графика окна очков собирается один раз, а в игровом цикле только blit.
def build_input_panel_cache():
    global _INPUT_PANEL_SURFACE
    panel = pg.Surface(ip_rect.size).convert_alpha()
    panel.fill((0, 0, 0, 0))
    local_panel = panel.get_rect()
    pg.draw.rect(panel, PNL, local_panel, border_radius=18)
    pg.draw.rect(panel, BRD, local_panel, 2, border_radius=18)
    title = f_menu_btn.render("ПОБЕДНЫЕ ОЧКИ", True, WHT).convert_alpha()
    panel.blit(title, title.get_rect(center=(local_panel.centerx, int(ip_h * 0.085))))
    hint = f_small.render("Введите число от 1 до 1000", True, GRY).convert_alpha()
    panel.blit(hint, hint.get_rect(center=(local_panel.centerx, int(ip_h * 0.185))))
    box_local = ip_box.move(-ip_rect.x, -ip_rect.y)
    pg.draw.rect(panel, ABG, box_local, border_radius=12)
    pg.draw.rect(panel, CYN, box_local, 2, border_radius=12)
    for label, rect in ip_keys:
        rr = rect.move(-ip_rect.x, -ip_rect.y)
        pg.draw.rect(panel, BTN, rr, border_radius=max(10, int(ip_kh * 0.20)))
        pg.draw.rect(panel, (88, 88, 88), rr, 1, border_radius=max(10, int(ip_kh * 0.20)))
        key_surf = _INPUT_KEY_CACHE.get(label)
        if key_surf is None:
            key_surf = f_key.render(label, True, WHT).convert_alpha()
            _INPUT_KEY_CACHE[label] = key_surf
        panel.blit(key_surf, key_surf.get_rect(center=rr.center))
    _INPUT_PANEL_SURFACE = panel

build_input_panel_cache()

