import array
import base64
import zlib

def _fade_tail(buf, rate, sec=0.03):
    k = int(rate * sec)
    for i in range(k):
        buf[len(buf) - 1 - i] *= i / k

def _norm(buf, level):
    peak = max(abs(v) for v in buf) or 1.0
    return [v / peak * level for v in buf]

def _synth_death(rate):
    # "ту-ду-ф": два нисходящих бас-удара подряд (по спектру эталонного звука смерти), басы мягкие
    n = int(rate * 0.34)
    buf = [0.0] * n
    def hit(t0, f_hi, f_lo, tau, dur, vol, att, decay):
        i0, ln, ph = int(t0 * rate), int(dur * rate), 0.0
        fade = int(rate * 0.014)
        for i in range(ln):
            t = i / rate
            ph += 2 * m.pi * (f_lo + (f_hi - f_lo) * m.exp(-t / tau)) / rate
            env = min(1.0, t / att) * m.exp(-t * decay)
            if i > ln - fade: env *= (ln - i) / fade
            v = (m.sin(ph) + 0.18 * m.sin(2 * ph)) * env * vol   # почти чистый синус - нежный бас
            if i0 + i < n: buf[i0 + i] += v
    hit(0.000, 345, 62, 0.045, 0.150, 1.00, 0.012, 4.0)   # "ту"
    hit(0.155, 240, 45, 0.070, 0.140, 1.00, 0.018, 2.5)   # "ду"
    buf = _norm(buf, 0.62)                                 # басы тише и мягче
    nz = 0.0                                               # "ф" и щелчок - ровно как раньше
    for i in range(n):
        t = i / rate
        nz += (rnd.uniform(-1, 1) - nz) * 0.30
        buf[i] += (nz * 0.10 * m.exp(-t * 9) + (rnd.uniform(-1, 1) * 0.25 * (1 - t / 0.004) if t < 0.004 else 0.0)) * 0.894
    _fade_tail(buf, rate, 0.012)
    return buf

def _synth_announce(rate):
    # двойной мягкий "колокольчик" - объявление об окончании раунда
    n = int(rate * 0.9)
    buf = [0.0] * n
    def bell(t0, f, dur, vol):
        i0, ln = int(t0 * rate), int(dur * rate)
        for i in range(ln):
            t = i / rate
            env = min(1.0, t / 0.006) * m.exp(-t * (5.5 / dur))
            v = (m.sin(2 * m.pi * f * t) + 0.4 * m.sin(2 * m.pi * f * 2.0 * t) + 0.15 * m.sin(2 * m.pi * f * 2.76 * t)) * env * vol
            if i0 + i < n: buf[i0 + i] += v
    bell(0.00, 523.3, 0.55, 0.8)
    bell(0.17, 784.0, 0.70, 1.0)
    _fade_tail(buf, rate)
    return _norm(buf, 0.8)

