_WIN_STEP = [7, 8, 9, 10, 11, 12, 13, 14, 16, 17, 19, 21, 23, 25, 28, 31, 34, 37, 41, 45, 50, 55, 60, 66, 73, 80, 88, 97, 107, 118, 130, 143, 157, 173, 190, 209, 230, 253, 279, 307, 337, 371, 408, 449, 494, 544, 598, 658, 724, 796, 876, 963, 1060, 1166, 1282, 1411, 1552, 1707, 1878, 2066, 2272, 2499, 2749, 3024, 3327, 3660, 4026, 4428, 4871, 5358, 5894, 6484, 7132, 7845, 8630, 9493, 10442, 11487, 12635, 13899, 15289, 16818, 18500, 20350, 22385, 24623, 27086, 29794, 32767]
_WIN_IDX = [-1, -1, -1, -1, 2, 4, 6, 8]

def _load_win(rate):
    raw = zlib.decompress(base64.b64decode(_WIN_B64))
    pred, idx, out = 0, 0, []
    for byte in raw:
        for code in (byte >> 4, byte & 15):
            step = _WIN_STEP[idx]
            d = step >> 3
            if code & 4: d += step
            if code & 2: d += step >> 1
            if code & 1: d += step >> 2
            pred += -d if code & 8 else d
            pred = -32768 if pred < -32768 else (32767 if pred > 32767 else pred)
            idx += _WIN_IDX[code & 7]
            idx = 0 if idx < 0 else (88 if idx > 88 else idx)
            out.append(pred / 32768.0)
    out = out[:_WIN_N]
    if rate != 44100:
        n = int(len(out) * rate / 44100)
        res = [0.0] * n
        for i in range(n):
            p = i * 44100 / rate; j = min(int(p), len(out) - 2); fr = p - j
            res[i] = out[j] * (1 - fr) + out[j + 1] * fr
        out = res
    return out

def _synth_drop(rate):
    # "па" - звук упавшей капельки: быстро растущий тон с коротким затуханием
    n = int(rate * 0.22)
    buf = [0.0] * n
    ph = 0.0
    for i in range(n):
        t = i / rate
        ph += 2 * m.pi * (380 + 900 * (1 - m.exp(-t / 0.022))) / rate
        env = min(1.0, t / 0.003) * m.exp(-t / 0.045)
        buf[i] = (m.sin(ph) + 0.12 * m.sin(2 * ph)) * env
        if t < 0.002: buf[i] += rnd.uniform(-1, 1) * 0.15
    _fade_tail(buf, rate, 0.02)
    return _norm(buf, 0.7)

def _synth_tick(rate, f_body):
    # реалистичное тиканье часов: резкий щелчок + короткий деревянный "корпус"
    n = int(rate * 0.12)
    buf = [0.0] * n
    prev = 0.0
    for i in range(n):
        t = i / rate
        nz = rnd.uniform(-1, 1)
        click = (nz - prev) * m.exp(-t * 700); prev = nz
        body = m.sin(2 * m.pi * f_body * t) * m.exp(-t * 110) * 0.9 + m.sin(2 * m.pi * f_body * 0.27 * t) * m.exp(-t * 70) * 0.6
        buf[i] = click * 0.7 + body
    _fade_tail(buf, rate, 0.01)
    return _norm(buf, 0.8)

snd_death, snd_end, snd_ticks, snd_win, snd_drop = None, None, [], None, None
try:
    if not pg.mixer.get_init(): pg.mixer.init(44100, -16, 1, 512)
    _fr, _fmt, _ch = pg.mixer.get_init()
    if _fmt == -16:
        def _mk_snd(samples, vol):
            ar = array.array('h')
            for v in samples:
                iv = int(max(-1.0, min(1.0, v)) * 32767)
                for _k in range(_ch): ar.append(iv)
            sn = pg.mixer.Sound(buffer=ar.tobytes()); sn.set_volume(vol)
            return sn
        snd_death = _mk_snd(_synth_death(_fr), 1.0)
        snd_end = _mk_snd(_synth_announce(_fr), 0.8)
        snd_win = _mk_snd(_load_win(_fr), 0.85)
        snd_drop = _mk_snd(_synth_drop(_fr), 0.6)
        snd_ticks = [_mk_snd(_synth_tick(_fr, 1900), 0.7), _mk_snd(_synth_tick(_fr, 1450), 0.7)]
except Exception:
    snd_death, snd_end, snd_ticks, snd_win, snd_drop = None, None, [], None, None

