class LocalRoom:
    """TCP авторитетный хост + UDP обнаружение комнат в локальной сети."""
    def __init__(self, role):
        self.role = role
        self.running = True
        self.connected = False
        self.discovered = []
        self.latest_state = None
        self.turn = 0
        self.sock = None
        self.client_sock = None
        self.lock = threading.Lock()
        self.send_lock = threading.Lock()
        # Клиентские команды поворота отправляются отдельным потоком.
        # Игровой цикл никогда не ждёт TCP sendall при нестабильном Wi-Fi.
        self.outgoing_turn = None
        self.outgoing_lock = threading.Lock()
        self.error = ""
        self.local_ip = self._local_ip()
        self.threads = []
        if role == "host":
            self._start_host()
        else:
            self._start_discovery()
            self._thread(self._client_send_loop)

    @staticmethod
    def _local_ip():
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            s.connect(("192.0.2.1", 80))
            ip = s.getsockname()[0]
        except Exception:
            ip = "127.0.0.1"
        finally:
            s.close()
        return ip

    def _thread(self, target, *args):
        t = threading.Thread(target=target, args=args, daemon=True)
        t.start()
        self.threads.append(t)

    def _start_host(self):
        try:
            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.sock.bind(("0.0.0.0", NET_TCP_PORT))
            self.sock.listen(1)
            self.sock.settimeout(0.25)
            self._thread(self._host_accept)
            self._thread(self._host_discovery)
        except Exception as ex:
            self.error = str(ex)

    def _host_accept(self):
        while self.running and self.sock:
            try:
                conn, addr = self.sock.accept()
                conn.settimeout(0.15)
                conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                self.client_sock = conn
                self.connected = True
                self._thread(self._host_receive, conn)
                break
            except socket.timeout:
                continue
            except Exception as ex:
                if self.running: self.error = str(ex)
                break

    def _host_receive(self, conn):
        buf = b""
        while self.running and conn is self.client_sock:
            try:
                chunk = conn.recv(4096)
                if not chunk: break
                buf += chunk
                while b"\n" in buf:
                    raw, buf = buf.split(b"\n", 1)
                    try:
                        msg = json.loads(raw.decode("utf-8"))
                        if msg.get("type") == "input":
                            self.turn = max(-1, min(1, int(msg.get("turn", 0))))
                    except Exception:
                        pass
            except socket.timeout:
                continue
            except Exception:
                break
        self.connected = False
        try: conn.close()
        except Exception: pass

    def _host_discovery(self):
        udp = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            udp.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            udp.bind(("0.0.0.0", NET_UDP_PORT))
            udp.settimeout(0.4)
            while self.running:
                try:
                    data, addr = udp.recvfrom(1024)
                    if data.startswith(b"CURVE_FEVER_DISCOVER"):
                        packet = json.dumps({"name":"Комната Curve Fevers", "ip":self.local_ip,
                                             "port":NET_TCP_PORT, "players":1}).encode("utf-8")
                        udp.sendto(packet, addr)
                except socket.timeout:
                    continue
                except Exception:
                    if self.running: time.sleep(0.2)
        finally:
            udp.close()

    def _start_discovery(self):
        self._thread(self._discover_loop)

    def _discover_loop(self):
        while self.running:
            udp = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            try:
                udp.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
                udp.settimeout(0.35)
                udp.bind(("", 0))
                # Общий broadcast плюс типичные подсети Android-hotspot/Windows.
                for broadcast_ip in ("255.255.255.255", "192.168.43.255", "192.168.1.255", "192.168.137.255"):
                    try: udp.sendto(b"CURVE_FEVER_DISCOVER", (broadcast_ip, NET_UDP_PORT))
                    except Exception: pass
                deadline = time.time() + 0.8
                while self.running and time.time() < deadline:
                    try:
                        data, addr = udp.recvfrom(2048)
                        info = json.loads(data.decode("utf-8"))
                        info["ip"] = addr[0]
                        info["seen"] = time.time()
                        with self.lock:
                            existing = next((x for x in self.discovered if x.get("ip") == info["ip"]), None)
                            if existing is None: self.discovered.append(info)
                            else: existing.update(info)
                    except socket.timeout:
                        continue
                    except Exception:
                        break
            except Exception as ex:
                self.error = str(ex)
            finally:
                udp.close()
            with self.lock:
                self.discovered[:] = [x for x in self.discovered if time.time() - x.get("seen",0) < 5.0]
            time.sleep(1.0)

    def connect(self, ip):
        self._thread(self._connect_worker, ip)

    def _connect_worker(self, ip):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(5.0)
            s.connect((ip, NET_TCP_PORT))
            s.settimeout(0.15)
            s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            self.client_sock = s
            self.connected = True
            buf = b""
            while self.running:
                try:
                    chunk = s.recv(16384)
                    if not chunk: break
                    buf += chunk
                    while b"\n" in buf:
                        raw, buf = buf.split(b"\n", 1)
                        try:
                            state = json.loads(raw.decode("utf-8"))
                            with self.lock: self.latest_state = state
                        except Exception:
                            pass
                except socket.timeout:
                    continue
                except Exception:
                    break
            self.connected = False
            try: s.close()
            except Exception: pass
        except Exception as ex:
            self.error = str(ex)
            self.connected = False

    def _client_send_loop(self):
        """Отправляет только последнюю команду поворота вне главного потока."""
        while self.running:
            packet = None
            with self.outgoing_lock:
                packet = self.outgoing_turn
                self.outgoing_turn = None
            s = self.client_sock
            if packet is not None and s is not None and self.connected:
                try:
                    s.sendall(packet)
                except socket.timeout:
                    # Не блокируем игру; следующая команда заменит устаревшую.
                    pass
                except Exception:
                    self.connected = False
            else:
                time.sleep(0.005)

    def send(self, obj):
        # Для клиента очередь из одного элемента: при задержке сети сохраняем
        # самую свежую команду, а не накапливаем старые повороты.
        try:
            packet = (json.dumps(obj, separators=(",", ":")) + "\n").encode("utf-8")
            with self.outgoing_lock:
                self.outgoing_turn = packet
        except Exception:
            pass

    def send_turn(self, turn):
        self.send({"type":"input", "turn":int(turn)})

    def send_state(self, state):
        s = self.client_sock
        if not s or not self.connected: return
        try:
            packet = (json.dumps(state, separators=(",", ":")) + "\n").encode("utf-8")
            with self.send_lock:
                s.sendall(packet)
        except Exception:
            self.connected = False

    def get_state(self):
        with self.lock:
            return self.latest_state

    def close(self):
        self.running = False
        for s in (self.client_sock, self.sock):
            try:
                if s: s.close()
            except Exception:
                pass

# ===== Bluetooth Classic RFCOMM (Android / Pydroid 3) =====
BT_UUID_TEXT = "7c6f6f4e-2b7a-4d6c-9a31-435552564546"
BT_SERVICE_NAME = "Curve Fevers"


def bt_android_setup(make_discoverable=False):
    """Возвращает Android BluetoothAdapter; оба телефона должны быть сопряжены заранее."""
    try:
        from jnius import autoclass
        try:
            from android.permissions import request_permissions
            try:
                request_permissions([
                    "android.permission.BLUETOOTH",
                    "android.permission.BLUETOOTH_ADMIN",
                    "android.permission.BLUETOOTH_CONNECT",
                    "android.permission.BLUETOOTH_SCAN",
                    "android.permission.BLUETOOTH_ADVERTISE",
                ])
            except Exception:
                pass
        except Exception:
            pass
        BluetoothAdapter = autoclass('android.bluetooth.BluetoothAdapter')
        adapter = BluetoothAdapter.getDefaultAdapter()
        if adapter is None:
            raise RuntimeError("На этом устройстве нет Bluetooth")
        if not adapter.isEnabled():
            raise RuntimeError("Сначала включи Bluetooth в настройках Android")
        return adapter
    except Exception as ex:
        raise RuntimeError(str(ex))


class BluetoothRoom:
    """Тот же интерфейс, что LocalRoom, но транспорт — Bluetooth Classic RFCOMM."""
    def __init__(self, role, device_address=None):
        self.role = role
        self.running = True
        self.connected = False
        self.latest_state = None
        self.turn = 0
        self.error = ""
        self.lock = threading.Lock()
        self.outgoing_lock = threading.Lock()
        self.outgoing_turn = None
        self.outgoing_state = None
        self.send_lock = threading.Lock()
        self.bt_socket = None
        self.server_socket = None
        self.input_stream = None
        self.output_stream = None
        self.threads = []
        self.adapter = bt_android_setup(make_discoverable=(role == "host"))
        self._thread(self._client_send_loop)
        if role == "host":
            self._thread(self._host_accept)
            self._thread(self._host_send_loop)
        else:
            self._thread(self._client_connect, device_address)

    def _thread(self, target, *args):
        t = threading.Thread(target=target, args=args, daemon=True)
        t.start()
        self.threads.append(t)

    @staticmethod
    def paired_devices():
        adapter = bt_android_setup(False)
        result = []
        devices = adapter.getBondedDevices().toArray()
        for dev in devices:
            try:
                result.append({"name": str(dev.getName() or "Android"), "address": str(dev.getAddress())})
            except Exception:
                pass
        return result

    def _host_accept(self):
        try:
            from jnius import autoclass
            UUID = autoclass('java.util.UUID')
            uuid = UUID.fromString(BT_UUID_TEXT)
            self.server_socket = self.adapter.listenUsingRfcommWithServiceRecord(BT_SERVICE_NAME, uuid)
            sock = self.server_socket.accept()
            self._attach_socket(sock)
        except Exception as ex:
            if self.running: self.error = "Bluetooth host: " + str(ex)

    def _client_connect(self, address):
        try:
            from jnius import autoclass
            UUID = autoclass('java.util.UUID')
            uuid = UUID.fromString(BT_UUID_TEXT)
            device = self.adapter.getRemoteDevice(address)
            sock = device.createRfcommSocketToServiceRecord(uuid)
            sock.connect()
            self._attach_socket(sock)
        except Exception as ex:
            if self.running: self.error = "Bluetooth connect: " + str(ex)

    def _attach_socket(self, sock):
        self.bt_socket = sock
        self.input_stream = sock.getInputStream()
        self.output_stream = sock.getOutputStream()
        self.connected = True
        self._thread(self._receive_loop)

    def _read_packet_loop(self):
        # Читаем небольшими блоками через Java byte[], не блокируя Pygame-поток.
        from jnius import jarray
        buf = jarray('b')(4096)
        pending = bytearray()
        while self.running and self.connected:
            count = self.input_stream.read(buf)
            if count < 0:
                break
            for i in range(count):
                pending.append(int(buf[i]) & 255)
            while b"\n" in pending:
                raw, _, rest = pending.partition(b"\n")
                pending = bytearray(rest)
                if raw:
                    try:
                        msg = json.loads(raw.decode("utf-8"))
                        if self.role == "host" and msg.get("type") == "input":
                            self.turn = max(-1, min(1, int(msg.get("turn", 0))))
                        elif self.role == "client" and msg.get("type") == "state":
                            with self.lock:
                                self.latest_state = msg
                    except Exception:
                        pass
        self.connected = False

    def _receive_loop(self):
        try:
            self._read_packet_loop()
        except Exception as ex:
            if self.running: self.error = "Bluetooth receive: " + str(ex)
        self.connected = False

    def _write_packet(self, packet):
        from jnius import jarray
        # Java byte[] использует signed byte.
        arr = jarray('b')([v if v < 128 else v - 256 for v in packet])
        with self.send_lock:
            self.output_stream.write(arr)
            self.output_stream.flush()

    def _client_send_loop(self):
        while self.running:
            packet = None
            with self.outgoing_lock:
                packet = self.outgoing_turn
                self.outgoing_turn = None
            if packet is not None and self.connected and self.role == "client":
                try:
                    self._write_packet(packet)
                except Exception as ex:
                    self.error = "Bluetooth send: " + str(ex)
                    self.connected = False
            else:
                time.sleep(0.005)

    def send(self, obj):
        try:
            packet = (json.dumps(obj, separators=(",", ":")) + "\n").encode("utf-8")
            with self.outgoing_lock:
                self.outgoing_turn = packet
        except Exception:
            pass

    def send_turn(self, turn):
        self.send({"type":"input", "turn":int(turn)})

    def _host_send_loop(self):
        while self.running:
            state = None
            with self.outgoing_lock:
                state = self.outgoing_state
                self.outgoing_state = None
            if state is not None and self.connected:
                try:
                    packet = (json.dumps(state, separators=(",", ":")) + "\n").encode("utf-8")
                    self._write_packet(packet)
                except Exception as ex:
                    self.error = "Bluetooth state: " + str(ex)
                    self.connected = False
            else:
                time.sleep(0.003)

    def send_state(self, state):
        if not self.connected or self.role != "host": return
        with self.outgoing_lock:
            self.outgoing_state = state

    def get_state(self):
        with self.lock:
            return self.latest_state

    def close(self):
        self.running = False
        self.connected = False
        for obj in (self.bt_socket, self.server_socket):
            try:
                if obj: obj.close()
            except Exception:
                pass


def net_player_data(pl):
    # Полный след не отправляем в каждом состоянии: только новые точки идут в trail_delta.
    return {"x":pl.x, "y":pl.y, "a":pl.a, "alv":pl.alv, "c":pl.c,
            "skin":pl.skin, "effects":pl.effects,
            "size":pl.size_mult, "wm":pl.wm, "gt":pl.gt, "gp":pl.gp}

def net_apply_player(pl, data):
    pl.x, pl.y, pl.a, pl.alv = float(data["x"]), float(data["y"]), float(data["a"]), bool(data["alv"])
    pl.skin = int(data.get("skin", 0))
    # На клиенте геометрия следа хранится на отдельном слое, а не в deque игрока.
    pl.tl.clear()
    pl.effects = {k:[] for k in pl.effects}; pl.effects.update({k:list(v) for k,v in data.get("effects", {}).items()})
    pl.size_mult = float(data.get("size", SZ))
    pl.wm, pl.gt, pl.gp = int(data.get("wm", 0)), int(data.get("gt", 0)), bool(data.get("gp", False))

def net_make_state():
    global net_seq, net_trail_pending
    net_seq += 1
    # Передаём только новые точки следа: так пакеты остаются небольшими.
    trail_delta = [list(points) for points in net_trail_pending]
    net_trail_pending = [[], []]
    countdown_ms = 5000
    if net_winner is not None and net_round_end_tick:
        countdown_ms = max(0, 5000 - (pg.time.get_ticks() - net_round_end_tick))
    return {"type":"state", "seq":net_seq, "round_id":net_round_id,
            "arena_size":[AW,AH],
            "players":[net_player_data(net_players[0]), net_player_data(net_players[1])],
            "trail_delta":trail_delta,
            "bonuses":[{"x":b.x,"y":b.y,"type":b.type} for b in bonuses],
            "winner":net_winner, "started":net_started, "countdown_ms":countdown_ms}

def net_begin_game(round_id=None):
    global arn, p1, bots, bonuses, net_players, net_history, net_trail_pending
    global net_trail_layers, net_trail_last
    global net_started, net_winner, spawn_timer, round_start_tick, net_seq, net_last_seq
    global net_status, net_round_id, net_round_end_tick
    arn = pg.Surface((AW, AH)).convert(); arn.fill(ABG)
    sp = spw_all(2)
    p1 = P(*sp[0], YEL)
    p2 = P(*sp[1], CYN)
    # В LAN-режиме темп и радиус поворота такие же спокойные, как в Solo Mode.
    for pl in (p1, p2):
        pl.base_speed = 1.00
        pl.base_turn = 0.045
        pl.cur_speed, pl.cur_turn = pl.base_speed, pl.base_turn
        pl.trail_delay = 12
        pl.gap_duration = 20
    net_players = [p1, p2]
    net_history = [deque(maxlen=12000), deque(maxlen=12000)]
    net_trail_pending = [[], []]
    net_trail_layers = [pg.Surface((AW, AH), pg.SRCALPHA), pg.Surface((AW, AH), pg.SRCALPHA)]
    net_trail_last = [None, None]
    if round_id is None:
        net_round_id += 1
    else:
        net_round_id = int(round_id)
    net_round_end_tick = 0
    # Начальные точки, чтобы след начинался точно с позиции головы.
    for i, pl in enumerate(net_players):
        point = (int(pl.x), int(pl.y), False)
        net_history[i].append(point)
        net_trail_pending[i].append(point)
    net_seq = 0
    net_last_seq = -1
    bots = [p2]
    bonuses = []
    net_started = pg.time.get_ticks()
    net_winner = None
    spawn_timer = 0
    round_start_tick = pg.time.get_ticks()
    drops.clear()
    net_status = ""

def net_draw_client_player(pl, history, target, trail_layer=None):
    # След уже нарисован на прозрачном слое при получении новых точек.
    if trail_layer is not None:
        target.blit(trail_layer, AR.topleft)
    # Голова рисуется штатной функцией; длинный след повторно не обрабатывается.
    saved = pl.tl
    pl.tl = deque()
    pl.drw(target)
    pl.tl = saved

def net_draw_button(rect, label, mouse, color=WHT):
    pg.draw.rect(scr, BTN, rect, border_radius=12)
    pg.draw.rect(scr, ON if rect.collidepoint(mouse) else BRD, rect, 2, border_radius=12)
    t = f2.render(label, True, color)
    scr.blit(t, t.get_rect(center=rect.center))

def net_online_press(pos):
    global game_state, net_page, net_room, net_role, net_status, net_manual_ip, net_selected, net_bt_devices
    if net_page == "menu":
        if net_host_btn.collidepoint(pos):
            net_role = "host"
            net_room = LocalRoom("host")
            if net_room.error:
                net_status = "Ошибка сервера: " + net_room.error
                net_room.close(); net_room = None
            else:
                net_page = "host_wait"
        elif net_scan_btn.collidepoint(pos):
            if net_room: net_room.close()
            net_role = "client"
            net_room = LocalRoom("client")
            net_page = "scan"
            net_status = "Ищем комнаты в локальной сети..."
        elif net_bt_host_btn.collidepoint(pos):
            try:
                net_role = "host"
                net_room = BluetoothRoom("host")
                net_page = "host_wait"
                net_status = "Включи видимость Bluetooth и жди друга"
            except Exception as ex:
                net_status = str(ex)
                net_room = None
        elif net_bt_scan_btn.collidepoint(pos):
            try:
                net_bt_devices = BluetoothRoom.paired_devices()
                net_page = "bt_devices"
                net_status = "Выбери уже сопряжённый телефон"
            except Exception as ex:
                net_status = str(ex)
        elif net_manual_btn.collidepoint(pos):
            net_manual_ip = ""
            net_page = "manual"
        elif net_back_btn.collidepoint(pos):
            game_state = "MENU"
    elif net_page == "bt_devices":
        if net_back_btn.collidepoint(pos):
            net_page = "menu"
        else:
            y0 = int(H*0.38)
            for i, info in enumerate(net_bt_devices[:7]):
                rr = pg.Rect(W//2-int(W*0.35), y0+i*int(H*0.075), int(W*0.70), int(H*0.065))
                if rr.collidepoint(pos):
                    try:
                        net_role = "client"
                        net_room = BluetoothRoom("client", info["address"])
                        net_page = "client_wait"
                        net_status = "Подключаемся по Bluetooth к " + info["name"]
                    except Exception as ex:
                        net_status = str(ex)
                    break
    elif net_page == "host_wait":
        if net_back_btn.collidepoint(pos):
            if net_room: net_room.close()
            net_room = None; net_page = "menu"
    elif net_page == "scan":
        if net_back_btn.collidepoint(pos):
            if net_room: net_room.close()
            net_room = None; net_page = "menu"
        else:
            y0 = int(H*0.34)
            with net_room.lock:
                found = list(net_room.discovered)
            for i, info in enumerate(found[:5]):
                rr = pg.Rect(W//2-int(W*0.35), y0+i*int(H*0.085), int(W*0.70), int(H*0.07))
                if rr.collidepoint(pos):
                    net_selected = i
                    net_room.connect(info["ip"])
                    net_page = "client_wait"
                    net_status = "Подключаемся к " + info["ip"]
                    break
    elif net_page == "manual":
        if manual_back_btn.collidepoint(pos):
            net_page = "menu"
        elif manual_connect_btn.collidepoint(pos):
            if net_manual_ip.count(".") == 3 and net_room is None:
                net_role = "client"; net_room = LocalRoom("client")
                net_room.connect(net_manual_ip)
                net_page = "client_wait"
                net_status = "Подключаемся к " + net_manual_ip
        else:
            for lab, rr in manual_keys:
                if rr.collidepoint(pos):
                    if lab == "<": net_manual_ip = net_manual_ip[:-1]
                    elif lab == ".":
                        if len(net_manual_ip) < 15 and (not net_manual_ip or not net_manual_ip.endswith(".")): net_manual_ip += "."
                    elif len(net_manual_ip) < 15: net_manual_ip += lab
                    break
    elif net_page == "client_wait":
        if net_back_btn.collidepoint(pos):
            if net_room: net_room.close()
            net_room = None; net_page = "menu"


