def _load_cards():
    imgs = {}
    for nm in _CARD_ANCHORS:
        pair, big = [], []
        for k in ('a', 'd'):
            try:
                im = pg.image.load(io.BytesIO(base64.b64decode("".join(_CARD_B64[nm + '_' + k]))), 'card.png').convert()
                pair.append(pg.transform.smoothscale(im, (CARD_W, CARD_H)))
                big.append(im)
            except Exception:
                pair.append(None); big.append(None)
        imgs[nm] = pair
        CARD_BIG[nm] = big
    return imgs

CARD_IMGS = _load_cards()

def card_key(col):
    key = _card_key_cache.get(col)
    if key is None:
        key = min(_CARD_ANCHORS, key=lambda n: sum((a - b) ** 2 for a, b in zip(_CARD_ANCHORS[n], col[:3])))
        _card_key_cache[col] = key
    return key

def card_for(col):
    """Карточка, чей цвет ближе всего к цвету змейки: (живая, мёртвая)."""
    return CARD_IMGS[card_key(col)]

_icon_cache = {}
def icon_for(col, alive, h):
    """Иконка змейки высотой h (масштабируется один раз и запоминается)."""
    ck = (col, alive, h)
    if ck not in _icon_cache:
        big = CARD_BIG.get(card_key(col), [None, None])[0 if alive else 1]
        _icon_cache[ck] = pg.transform.smoothscale(big, (max(1, int(h * 0.75)), h)) if big is not None else None
    return _icon_cache[ck]

podium_cache = [None, None]  # [ключ, готовая картинка подиума]: подиум рисуется один раз, а не каждый кадр

def build_podium(places):
    """places: [(индекс, имя, очки, цвет)] 1-3 места. Иконки стоят на возвышенности цвета 1 места:
    1 место по центру и выше всех, 2 слева ниже, 3 справа ниже всех; на возвышенности - «Победители матча»."""
    col1 = places[0][3]
    dark = lambda c, k: (int(c[0] * k), int(c[1] * k), int(c[2] * k))
    _bc = dark(col1, 0.68)  # цвет нижней плиты, на ней пишется надпись
    lum = 0.299 * _bc[0] + 0.587 * _bc[1] + 0.114 * _bc[2]
    tcol = (20, 20, 20) if lum > 140 else WHT
    ih = int(AR.w * 0.19); iw = int(ih * 0.75)
    bw_, gap = iw + 26, 6
    hc, hl, hr = int(ih * 0.62), int(ih * 0.42), int(ih * 0.26)
    title = f2.render("Победители матча", True, tcol).convert_alpha()
    base_h = int(title.get_height() * 1.6)
    blocks_w = bw_ * 3 + gap * 2
    pad = 36
    w_ = max(blocks_w, title.get_width() + 40) + pad * 2
    h_ = pad + ih + hc + base_h + pad
    surf = pg.Surface((w_, h_), pg.SRCALPHA)
    pg.draw.rect(surf, (0, 0, 0, 170), surf.get_rect(), border_radius=16)
    x0 = (w_ - blocks_w) // 2
    base_top = pad + ih + hc
    # (место, ступень, высота ступени): слева 2 место, по центру 1, справа 3
    for place, slot, bh, shade in ((0, 1, hc, 1.0), (1, 0, hl, 0.82), (2, 2, hr, 0.82)):
        bx = x0 + slot * (bw_ + gap)
        pl_ = places[place] if place < len(places) else None
        if pl_ is None: continue
        pg.draw.rect(surf, dark(col1, shade), (bx, base_top - bh, bw_, bh))
        pg.draw.rect(surf, dark(col1, 0.5), (bx, base_top - bh, bw_, bh), 2)
        num = f1.render(str(place + 1), True, dark(col1, 0.55)).convert_alpha()
        surf.blit(num, num.get_rect(center=(bx + bw_ // 2, base_top - bh // 2)))
        icon = icon_for(pl_[3], True, ih)
        ix, iy = bx + (bw_ - iw) // 2, base_top - bh - ih
        if icon is not None: surf.blit(icon, (ix, iy))
        else: pg.draw.rect(surf, pl_[3], (ix, iy, iw, ih))
        bar_h = int(ih * 0.17)
        bar = pg.Surface((iw, bar_h), pg.SRCALPHA); bar.fill((0, 0, 0, 190))
        surf.blit(bar, (ix, iy + ih - bar_h))
        txt = "%s | %d" % (pl_[1], pl_[2])
        lt = f_card.render(txt, True, WHT).convert_alpha()
        if lt.get_width() > iw - 6: lt = f_card2.render(txt, True, WHT).convert_alpha()
        surf.blit(lt, lt.get_rect(center=(ix + iw // 2, iy + ih - bar_h // 2)))
    pg.draw.rect(surf, dark(col1, 0.68), (x0, base_top, blocks_w, base_h))
    pg.draw.rect(surf, dark(col1, 0.5), (x0, base_top, blocks_w, base_h), 2)
    surf.blit(title, title.get_rect(center=(x0 + blocks_w // 2, base_top + base_h // 2)))
    return surf

f_card = pg.font.SysFont(None, max(14, int(W * 0.021)))
f_card2 = pg.font.SysFont(None, max(12, int(W * 0.017)))
# ============================================================================================================

def ctxt_cached(font, text, color):
    k = (id(font), text, color)
    r = _TXT_CACHE.get(k)
    if r is None:
        if len(_TXT_CACHE) > 400: _TXT_CACHE.clear()
        r = _TXT_CACHE[k] = font.render(text, True, color)
    return r

_SHADE_CACHE = {}
def shade_cached(size, alpha=170):
    k = (size, alpha)
    r = _SHADE_CACHE.get(k)
    if r is None:
        r = pg.Surface(size, pg.SRCALPHA); r.fill((0, 0, 0, alpha)); _SHADE_CACHE[k] = r
    return r

# Сборщик мусора: все объекты, созданные при запуске, выводим из-под сборки,
# а порог поднимаем, чтобы он не вклинивался в середину кадра.
gc.collect(); gc.freeze(); gc.set_threshold(100000, 50, 100)

# ===== АДАПТИВНЫЙ ОПТИМИЗАТОР FPS =====
# Следит за временем кадра. Если FPS сильно проседает - ступенчато снижает нагрузку:
#   ур.1+: боты, которые едут ПРЯМО (bd == 0) и которым ничего не грозит, думают вдвое реже;
#   ур.2+: дополнительно временно выключается декор следа скинов.
# Бот, который поворачивает или которому грозит столкновение, ВСЕГДА думает по расписанию
# (иначе он держал бы старый поворот и крутился по кругу). Когда FPS восстановился,
# нагрузка возвращается к обычной.
perf_ema, perf_lvl, perf_hold, perf_pass, reg_tick = 28.6, 0, 0, 0, 0
# «Усиленное мышление»: пока FPS в норме, каждый бот думает вдвое чаще (раз в 3 кадра вместо 6).
# При любой просадке выключается на ~20 секунд, чтобы не раскачивать FPS туда-сюда.
perf_dbl_hold = 0
PERF_BAD, PERF_GOOD = 33.0, 30.0  # мс на кадр при потолке 35 FPS (28.6 мс): хуже ~30 FPS - упрощаем, держим потолок - возвращаем качество

def game_menu_exit():
    # выход из игры в меню (то же, что делала кнопка «В МЕНЮ»)
    global game_state, paused, pause_snap, bgm_win_until, bgm_paused_for_win, bgm_wait_until
    paused = False; pause_snap = None
    bgm_win_until = 0
    bgm_paused_for_win = False
    if bgm_loaded and not pg.mixer.music.get_busy():
        bgm_wait_until = 0
        pg.mixer.music.set_volume(BGM_BASE_VOL)
        pg.mixer.music.play()
    game_state = "MENU"

def toggle_pause():
    # пауза замораживает игру; при выходе из паузы таймеры раунда сдвигаются на время паузы
    global paused, pause_t0, pause_snap, round_start_tick, round_end_tick, end_snd_due, solo_dead_tick
    now = pg.time.get_ticks()
    pause_snap = None
    if not paused:
        paused, pause_t0 = True, now
        return
    dt = now - pause_t0
    paused = False
    if round_start_tick is not None: round_start_tick += dt
    round_end_tick += dt
    if end_snd_due: end_snd_due += dt
    if solo_dead_tick: solo_dead_tick += dt  # соло: таймер между смертью и новым стартом тоже стоит на паузе

last_game_press = 0
def game_press(pos):
    # на Android касание приходит и как FINGERDOWN, и как «мышиное» событие: повтор в течение 300 мс игнорируем
    global last_game_press
    _t = pg.time.get_ticks()
    if _t - last_game_press < 300: return
    last_game_press = _t
    if solo_mode:
        if exit_btn.collidepoint(pos): game_menu_exit()
        elif solo_pause_btn.collidepoint(pos): toggle_pause()
    elif MENU_BTN.collidepoint(pos): game_menu_exit()
    elif PAUSE_BTN.collidepoint(pos): toggle_pause()

running = True
while running:
    mx, my = pg.mouse.get_pos()
    
    for e in pg.event.get():
        if e.type == pg.QUIT: 
            running = False
        elif e.type in (pg.FINGERDOWN, pg.FINGERMOTION):
            # FINGER-координаты нормализованы относительно окна; берём размер самой Surface,
            # а не display.Info, чтобы исключить вертикальное смещение на Android.
            sw, sh = scr.get_size()
            # SDL FINGERDOWN отдаёт координаты 0..1; переводим их в координаты
            # fullscreen Surface (те же координаты, в которых расположены кнопки).
            fx = max(0.0, min(0.999999, float(e.x)))
            fy = max(0.0, min(0.999999, float(e.y)))
            pos = (int(fx * sw), int(fy * sh))
            tch[e.finger_id] = pos
            if e.type == pg.FINGERDOWN:
                if game_state in ("MENU", "PROFILE", "SETTINGS", "BOT_SELECT"):
                    last_finger = pg.time.get_ticks()
                    safe_menu_press(pos)
                elif game_state == "SKINS":
                    last_finger = pg.time.get_ticks()
                    skins_press(pos)
                elif game_state == "ONLINE":
                    net_online_press(pos)
                elif game_state == "NET_GAME":
                    if exit_btn.collidepoint(pos):
                        if net_room: net_room.close()
                        net_room = None; net_role = None; game_state = "MENU"
                elif game_state == "GAME":
                    game_press(pos)
        elif e.type == pg.FINGERUP: 
            tch.pop(e.finger_id, None)
        elif e.type == pg.MOUSEBUTTONDOWN:
            mdn = True
            _mouse_age = pg.time.get_ticks() - last_finger
            # Принимаем и обычное мышиное событие, и SDL touch-mouse fallback.
            # Дубликат FINGERDOWN отсекается по времени, но если FINGERDOWN не пришёл,
            # нажатие по-прежнему обрабатывается через e.pos.
            if game_state in ("MENU", "PROFILE", "SETTINGS", "BOT_SELECT"):
                # SDL touch emulation can deliver this event in addition to FINGERDOWN.
                if not getattr(e, 'touch', False) and _mouse_age > 450:
                    safe_menu_press(e.pos)
            elif game_state == "SKINS":
                if _mouse_age > 450:
                    skins_press(e.pos)
            elif game_state == "ONLINE":
                if _mouse_age > 450:
                    net_online_press(e.pos)
            elif game_state == "NET_GAME":
                if exit_btn.collidepoint(e.pos):
                    if net_room: net_room.close()
                    net_room = None; net_role = None; game_state = "MENU"
            elif game_state == "GAME":
                if not getattr(e, 'touch', False): game_press(e.pos)
        elif e.type == pg.MOUSEBUTTONUP: 
            mdn = False
        elif e.type == pg.KEYDOWN: 
            kl = True if e.key == pg.K_LEFT else kl
            kr = True if e.key == pg.K_RIGHT else kr
            if game_state == "ONLINE" and net_page == "manual":
                if e.key == pg.K_BACKSPACE: net_manual_ip = net_manual_ip[:-1]
                elif e.unicode in "0123456789." and len(net_manual_ip) < 15: net_manual_ip += e.unicode
            if game_state == "PROFILE" and profile_nick_edit:
                if e.key in (pg.K_RETURN, pg.K_KP_ENTER):
                    profile_nick = profile_nick.strip()[:16] or "Игрок"
                    profile_nick_edit = False
                    try: pg.key.stop_text_input()
                    except Exception: pass
                    prefs_save()
                elif e.key == pg.K_BACKSPACE:
                    profile_nick = profile_nick[:-1]
                    prefs_save()
                elif len(e.unicode) == 1 and e.unicode.isprintable() and not e.unicode.isspace() or (len(e.unicode) == 1 and e.unicode == " "):
                    if len(profile_nick) < 16:
                        profile_nick += e.unicode
                        prefs_save()
            elif game_state in ("MENU", "SETTINGS") and input_mode:
                if e.key in (pg.K_RETURN, pg.K_KP_ENTER): input_ok()
                elif e.key == pg.K_BACKSPACE: input_str = input_str[:-1]
                elif len(e.unicode) == 1 and e.unicode in "0123456789": input_add(e.unicode)
            if e.key == pg.K_ESCAPE: 
                if game_state == "PROFILE":
                    if not profile_nick.strip(): profile_nick = "Игрок"
                    prefs_save()
                    profile_open = False; profile_nick_edit = False; profile_saved_until = 0
                    game_state = "MENU"
                    try: pg.key.stop_text_input()
                    except Exception: pass
                elif input_mode: input_mode = False
                elif game_state == "BOT_SELECT": game_state = "SETTINGS"
                elif game_state == "SETTINGS": game_state = "MENU"
                elif game_state == "GAME": game_state = "MENU"
                elif game_state == "SKINS":
                    if sk_page == "home": game_state = "MENU"
                    else: sk_page = "home"
                elif game_state in ("ONLINE", "NET_GAME"):
                    if net_room: net_room.close()
                    net_room = None; net_role = None; game_state = "MENU"
                else: running = False
        elif hasattr(pg, "TEXTINPUT") and e.type == pg.TEXTINPUT:
            # On Android the on-screen keyboard commonly sends TEXTINPUT rather
            # than KEYDOWN unicode. Handle committed IME text here.
            if game_state == "PROFILE" and profile_nick_edit:
                _incoming = getattr(e, "text", "")
                if _incoming:
                    _clean = "".join(ch for ch in _incoming if ch.isprintable())
                    if _clean:
                        profile_nick = (profile_nick + _clean)[:16]
                        prefs_save()
        elif e.type == pg.KEYUP: 
            kl = False if e.key == pg.K_LEFT else kl
            kr = False if e.key == pg.K_RIGHT else kr

    upd_bgm()

    # Автоматический переход из ожидания в матч после TCP-подключения.
    # Хост запускает раунд, когда клиент действительно подключился; клиент
    # ждёт первый пакет состояния от хоста, чтобы оба начали с одной сессии.
    if game_state == "ONLINE" and net_room:
        if net_page == "host_wait" and net_room.connected:
            net_begin_game()
            game_state = "NET_GAME"
            net_page = "playing"
        elif net_page == "client_wait":
            if net_room.error:
                net_status = "Ошибка подключения: " + net_room.error
            elif net_room.connected:
                first_state = net_room.get_state()
                if first_state and first_state.get("type") == "state" and first_state.get("players"):
                    net_begin_game(round_id=int(first_state.get("round_id", 1)))
                    game_state = "NET_GAME"
                    net_page = "playing"
                else:
                    net_status = "Соединение установлено. Ждём запуск комнаты..."

    scr.fill(BG)
    
    if game_state == "MENU":
        # Возвращён исходный однотонный фон и плоская серая палитра.
        draw_classic_menu_title(scr)
        subtitle = ctxt_cached(f_menu_sub, "ЗМЕЙКИ  •  СКОРОСТЬ  •  СОРЕВНОВАНИЕ", GRY)
        scr.blit(subtitle, subtitle.get_rect(center=(W // 2, int(H * 0.365))))

        draw_classic_menu_button(scr, start_btn, "КЛАССИЧЕСКИЙ", (mx, my), accent=True)
        draw_classic_menu_button(scr, solo_btn, "СОЛО", (mx, my), accent=True)
        draw_classic_menu_button(scr, online_btn, "ОНЛАЙН", (mx, my), accent=True)
        draw_classic_menu_button(scr, wp_btn, "ПАРАМЕТРЫ ИГРЫ", (mx, my))
        draw_classic_menu_button(scr, skins_btn, "СКИНЫ", (mx, my), accent=True)
        draw_classic_menu_button(scr, knockout_btn, "НОКАУТ", (mx, my))
        draw_classic_menu_button(scr, rating_btn, "РЕЙТИНГ", (mx, my))

        # Компактная кнопка профиля в правом верхнем углу.
        pg.draw.rect(scr, BTN, profile_btn, border_radius=12)
        pg.draw.rect(scr, ON if profile_btn.collidepoint((mx, my)) else BRD, profile_btn, 2, border_radius=12)
        _pn = ctxt_cached(f_menu_btn, profile_nick[:14], WHT)
        scr.blit(_pn, _pn.get_rect(center=profile_btn.center))

        if input_mode:
            # Непрозрачная заливка дешевле полноэкранного alpha-blit; меню под окном не нужно.
            scr.fill((9, 9, 9))
            scr.blit(_INPUT_PANEL_SURFACE, ip_rect.topleft)
            # Подсвечиваем только активную клавишу поверх готовой панели.
            for lb, rc in ip_keys:
                if rc.collidepoint((mx, my)):
                    pg.draw.rect(scr, ON, rc, border_radius=max(10, int(ip_kh * 0.20)))
                    key_surf = _INPUT_KEY_CACHE[lb]
                    scr.blit(key_surf, key_surf.get_rect(center=rc.center))
                    break
            if input_str:
                it = ctxt_cached(f_in, input_str + ("|" if (pg.time.get_ticks() // 500) % 2 == 0 else ""), WHT)
            else:
                it = ctxt_cached(f_in, str(target_score), GRY)
            scr.blit(it, it.get_rect(center=ip_box.center))
        
    elif game_state == "SETTINGS":
        scr.fill(BG)
        _st = ctxt_cached(f_menu, "ПАРАМЕТРЫ ИГРЫ", WHT)
        scr.blit(_st, _st.get_rect(center=(W//2, int(H*0.25))))
        _ss = ctxt_cached(f_small, "Настройки классического режима", GRY)
        scr.blit(_ss, _ss.get_rect(center=(W//2, int(H*0.32))))
        draw_classic_menu_button(scr, settings_score_btn, "КОЛ. ОЧКОВ  ·  %d" % target_score, (mx,my), accent=True)
        draw_classic_menu_button(scr, settings_bots_btn, "КОЛ. БОТОВ  ·  %d" % sum(BOT_ENABLED), (mx,my), accent=True)
        draw_classic_menu_button(scr, settings_back_btn, "НАЗАД", (mx,my))
        if input_mode:
            scr.fill((9, 9, 9))
            scr.blit(_INPUT_PANEL_SURFACE, ip_rect.topleft)
            for lb, rc in ip_keys:
                if rc.collidepoint((mx, my)):
                    pg.draw.rect(scr, ON, rc, border_radius=max(10, int(ip_kh * 0.20)))
                    key_surf = _INPUT_KEY_CACHE[lb]
                    scr.blit(key_surf, key_surf.get_rect(center=rc.center))
                    break
            if input_str:
                it = ctxt_cached(f_in, input_str + ("|" if (pg.time.get_ticks() // 500) % 2 == 0 else ""), WHT)
            else:
                it = ctxt_cached(f_in, str(target_score), GRY)
            scr.blit(it, it.get_rect(center=ip_box.center))

    elif game_state == "BOT_SELECT":
        scr.fill(BG)
        _bt = ctxt_cached(f_menu, "ВЫБОР БОТОВ", WHT)
        scr.blit(_bt, _bt.get_rect(center=(W//2, int(H*0.22))))
        _bhint = ctxt_cached(f_small, "Нажми на змейку, чтобы включить или отключить бота", GRY)
        scr.blit(_bhint, _bhint.get_rect(center=(W//2, int(H*0.31))))
        _bot_portraits = get_bot_icon_surfaces((_bot_icon_w, _bot_icon_h))
        _disabled_portraits = get_bot_disabled_icon_surfaces((_bot_icon_w, _bot_icon_h))
        for _i, _rc in enumerate(bot_icon_rects):
            _active = BOT_ENABLED[_i]
            _portrait = _bot_portraits[_i][0] if _active else _disabled_portraits[_i]
            if _portrait is not None:
                scr.blit(_portrait, _rc.topleft)
            else:
                pg.draw.rect(scr, BOT_BASE_COLORS[_i], _rc)
            pg.draw.rect(scr, GRN if _active else BRD, _rc, max(3, int(W*0.004)), border_radius=max(8, int(_bot_icon_w*0.06)))
            _num = ctxt_cached(f_menu_btn, "БОТ %d" % (_i+1), WHT if _active else GRY)
            scr.blit(_num, _num.get_rect(center=(_rc.centerx, _rc.bottom + int(H*0.028))))
        _count = ctxt_cached(f_menu_btn, "ВКЛЮЧЕНО: %d / 5" % sum(BOT_ENABLED), GRN)
        scr.blit(_count, _count.get_rect(center=(W//2, int(H*0.71))))
        draw_classic_menu_button(scr, bot_back_btn, "НАЗАД", (mx,my))

    elif game_state == "PROFILE":
        # Профиль — отдельный экран: меню под ним не отрисовывается.
        scr.fill((8, 8, 8))
        pg.draw.rect(scr, PNL, profile_panel, border_radius=22)
        pg.draw.rect(scr, BRD, profile_panel, 2, border_radius=22)
        pg.draw.line(scr, BRD, (profile_mid_x, profile_panel.y + int(profile_panel.h*0.025)),
                     (profile_mid_x, profile_bottom_y - int(profile_panel.h*0.025)), max(2, int(W*0.004)))
        pg.draw.line(scr, BRD, (profile_panel.x + int(profile_panel.w*0.035), profile_bottom_y - int(profile_panel.h*0.025)),
                     (profile_panel.right - int(profile_panel.w*0.035), profile_bottom_y - int(profile_panel.h*0.025)), max(2, int(W*0.004)))

        # Левая колонка: ник, статусная иконка и предпросмотр выбранного скина.
        pg.draw.rect(scr, ABG, profile_nick_rect, border_radius=24)
        pg.draw.rect(scr, CYN if profile_nick_edit else BRD, profile_nick_rect, 2, border_radius=24)
        _nick_text = profile_nick if profile_nick else "Игрок"
        _nl = ctxt_cached(f2, _nick_text + ("  |" if profile_nick_edit else ""), CYN if profile_nick_edit else WHT)
