        _elo_value = profile_fit_text("0", int(profile_elo_rect.w*0.88), int(W*0.036), WHT)
        scr.blit(_elo_title, _elo_title.get_rect(center=(profile_elo_rect.centerx, profile_elo_rect.centery - int(profile_elo_rect.h*0.20))))
        scr.blit(_elo_value, _elo_value.get_rect(center=(profile_elo_rect.centerx, profile_elo_rect.centery + int(profile_elo_rect.h*0.20))))

