                pg.draw.rect(scr,BTN,rr,border_radius=10); pg.draw.rect(scr,ON if rr.collidepoint((mx,my)) else BRD,rr,2,border_radius=10)
                label=f2.render(info.get("name","Комната Curve Fevers"),True,WHT)
